try:
    print('>>> x = slice(0)')
    print('>>> y = ""')
    print('>>> x &= y')
    print('>>> x')
    x = slice(0)
    y = ""
    x &= y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
